			}
			if msg := err.Error(); !strings.Contains(msg, `"`+tc.wantID+`"`) || !strings.Contains(msg, tc.wantMsg) {
				t.Fatalf("error %q must name policy %q and mention %q", msg, tc.wantID, tc.wantMsg)
			}
		})
	}
}

